"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.parse
import urllib.request


DEFAULT_LIMIT = 1000
MAX_RETRY_ATTEMPTS = 20
MAX_RESTARTS = 3


class InvalidCursor(Exception):
    """The server rejected our cursor; the export must start over."""


def _get_json(url, timeout=30):
    """GET url, retrying 429s and translating invalid cursors.

    A 429 must be retried with the identical request (same method, path and
    query), so we keep the URL untouched and only wait for Retry-After.
    """
    attempts = 0
    while True:
        try:
            with urllib.request.urlopen(url, timeout=timeout) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code == 429:
                attempts += 1
                if attempts > MAX_RETRY_ATTEMPTS:
                    raise
                retry_after = exc.headers.get("Retry-After")
                try:
                    delay = float(retry_after)
                except (TypeError, ValueError):
                    delay = 1.0
                time.sleep(max(0.0, delay))
                continue
            if exc.code == 400:
                try:
                    payload = json.load(exc)
                except (ValueError, OSError):
                    payload = {}
                if isinstance(payload, dict) and payload.get("error") == "invalid_cursor":
                    raise InvalidCursor() from exc
            raise


def fetch_payouts(base_url, limit=DEFAULT_LIMIT):
    """Return every payout, following v2 cursors until the export is drained.

    Windows overlap at their edges, so payouts are deduplicated by their
    unique ``id``. A payout is therefore emitted exactly once even when it
    appears at the end of one window and the start of the next.
    """
    endpoint = f"{base_url}/v2/payouts"
    seen = set()
    payouts = []
    cursor = None
    restarts = 0

    while True:
        params = {"limit": limit}
        if cursor is not None:
            params["cursor"] = cursor
        url = f"{endpoint}?{urllib.parse.urlencode(params)}"

        try:
            page = _get_json(url)
        except InvalidCursor:
            if restarts >= MAX_RESTARTS:
                raise
            restarts += 1
            cursor = None
            continue

        before = len(payouts)
        for payout in page.get("payouts", []):
            payout_id = payout["id"]
            if payout_id not in seen:
                seen.add(payout_id)
                payouts.append(payout)

        if page.get("drained"):
            return payouts

        next_cursor = page.get("cursor")
        if not next_cursor:
            raise RuntimeError("API returned a partial export without a cursor")
        if next_cursor == cursor and len(payouts) == before:
            raise RuntimeError("API returned the same cursor without new payouts")
        cursor = next_cursor


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    with open(args.out, "w") as f:
        for p in payouts:
            f.write(json.dumps(p) + "\n")
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

